#100 #CS example: Simple report with adjacency constructions #2 #Demonstrates how to use the API to write out a simple report to a file #0 #using System;^using System.IO;^using System.Text;^using DB.Api;^using DB.Extensibility.Contracts;^using System.Windows.Forms;^^namespace DB.Extensibility.Scripts^{^ public class SimpleReport : ScriptBase, IScript^ {^ public override void BeforeEnergyIdfGeneration()^ {^ StringBuilder report = new StringBuilder();^^ Site site = ApiEnvironment.Site;^ report.AppendFormat("Site: {0}
", site.GetAttribute("Title"));^^ foreach (Building building in site.Buildings)^ {^ PrintBuilding(building, report);^ foreach (BuildingBlock block in building.BuildingBlocks)^ {^ PrintBlock(block, report);^ foreach (Zone zone in block.Zones)^ {^ PrintZone(zone, report);^ foreach (Surface surface in zone.Surfaces)^ {^ PrintSurface(surface, report);^ foreach (Adjacency adjacency in surface.Adjacencies)^ {^ PrintAdjacency(adjacency, report);^ foreach (Opening opening in adjacency.Openings)^ {^ PrintOpening(opening, report);^^ }^ }^ }^ }^ }^ }^^ File.WriteAllText(@"C:eport.txt", report.ToString());^ }^^ private void PrintBuilding(Building building, StringBuilder report)^ {^ report.AppendFormat("+ Building: {0}
", building.GetAttribute("Title"));^ }^^ private void PrintBlock(BuildingBlock block, StringBuilder report)^ {^ report.AppendFormat(" + Block: {0}
", block.GetAttribute("Title"));^ report.AppendFormat(" - Type: {0}
", block.Type);^ report.AppendFormat(" - Height: {0}
", block.Height);^ }^^ private void PrintZone(Zone zone, StringBuilder report)^ {^ report.AppendFormat(" + Zone: {0}
", zone.GetAttribute("Title"));^ report.AppendFormat(" - Area: {0}
", zone.FloorArea);^ report.AppendFormat(" - Is Merged: {0}
", zone.IsChildZone);^ }^^ private void PrintSurface(Surface surface, StringBuilder report)^ {^ report.AppendFormat(" + Surface: {0}
", surface.GetAttribute("Title"));^ report.AppendFormat(" - Type: {0}
", surface.Type);^ report.AppendFormat(" - Area: {0}
", surface.Area);^ report.AppendFormat(" - Tilt: {0}
", surface.Tilt);^ }^^ private void PrintAdjacency(Adjacency adjacency, StringBuilder report)^ {^ Site site = ApiEnvironment.Site;^ Table table = site.GetTable("Constructions");^ Record record = table.Records.GetRecordFromHandle(adjacency.ConstructionId);^ string ConstructionName = record["Name"];^^ report.AppendFormat(" + Adjacency: {0}
", adjacency.AdjacencyCondition);^ report.AppendFormat(" - Area: {0}
", adjacency.Area);^ report.AppendFormat(" - Construction name: {0}
", ConstructionName);^ }^ ^ private void PrintOpening(Opening opening, StringBuilder report)^ {^ Site site = ApiEnvironment.Site;^^ if (opening.Type == OpeningType.Window) {^ // window^ Table table = site.GetTable("Glazing");^ Record record = table.Records.GetRecordFromHandle(opening.ConstructionId);^ string ConstructionName = record["Name"];^^ report.AppendFormat(" + Window: {0}
", "-");^ report.AppendFormat(" - Area: {0}
", opening.Area);^ report.AppendFormat(" - Glazing name: {0}
", ConstructionName);^^ } else if (opening.Type == OpeningType.Door) {^ // door^ Table table = site.GetTable("Constructions");^ Record record = table.Records.GetRecordFromHandle(opening.ConstructionId);^ string ConstructionName = record["Name"];^^ report.AppendFormat(" + Door: {0}
", "-");^ report.AppendFormat(" - Area: {0}
", opening.Area);^ report.AppendFormat(" - Construction name: {0}
", ConstructionName);^^ } else if (opening.Type == OpeningType.Vent) {^ // vent^ Table table = site.GetTable("Vents");^ int ventId = Int32.Parse(opening.GetAttribute("VentType"));^ Record record = table.Records.GetRecordFromHandle(ventId);^ string ventName = record["Name"];^^ report.AppendFormat(" + Vent: {0}
", "-");^ report.AppendFormat(" - Area: {0}
", opening.Area);^ report.AppendFormat(" - Vent name: {0}
", ventName);^^ } else if (opening.Type == OpeningType.Surface) {^ // surface^ Table table = site.GetTable("Constructions");^ Record record = table.Records.GetRecordFromHandle(opening.ConstructionId);^ string ConstructionName = record["Name"];^^ report.AppendFormat(" + Surface: {0}
", "-");^ report.AppendFormat(" - Area: {0}
", opening.Area);^ report.AppendFormat(" - Construction name: {0}
", ConstructionName);^ } else if (opening.Type == OpeningType.Hole) {^ // hole^ report.AppendFormat(" + Hole: {0}
", "-");^ report.AppendFormat(" - Area: {0}
", opening.Area);^ report.AppendFormat(" - Construction name: {0}
", "N/A");^ } ^ }^ }^}^

